import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Quote: single main items, base premium + first insurance + fee ---
  it("single sword (base 100 G) → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("single amulet (base 60 G) → premium 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("single staff (base 80 G) → premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("single potion (base 40 G) → premium 49 G (40 + 4 first insurance + 5 fee)");

  // --- Components and building blocks ---
  it.todo("1 rune → base premium 25 G");
  it.todo("2 runes → base premium 50 G");
  it.todo("3 runes → base premium 60 G (block of 3 alike applies)");
  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
  it.todo("7 runes → base premium 175 G (no block for 7)");
  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword adds 50 % of the sword's base premium (50 G surcharge)");
  it.todo("sword with enchantment exactly 5 → 30 % high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment exactly 5 → both surcharges apply");

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword + plain amulet → curse surcharge is 50 G (50 % of the cursed item only), policy base 210 G before further modifiers and fee",
  );

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("second quote in the scenario → 15 % follow-up contract discount applies");
  it.todo("first insurance surcharge applies to every item, even on a follow-up contract");

  // --- Rounding ---
  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // --- Quote errors ---
  it.todo("quote with an unknown item type (broomstick) → error, no results");

  // --- Claims: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("damage below the deductible → payout 0 G");

  // --- Claims: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment exactly 8, damage 1000 G → payout 400 G (50 % rule applies, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");

  // --- Claims: deductible per damage event ---
  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claims: cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block discount does not affect the insurance sum)");
  it.todo("cursed sword (premium 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("sword insured, two claims of 1500 G: first → payout 1400 G, remaining cap 600 G");
  it.todo("sword insured, two claims of 1500 G: second → payout 600 G, remaining cap 0 G");

  // --- Claims: multiple items of the same type ---
  it.todo("two swords insured, both damaged → each damage entry gets its own deductible");
  it.todo("more damage entries of a type than insured items → error, whole claim rejected");

  // --- Claims: rounding ---
  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down)");

  // --- Claim errors ---
  it.todo("claim damaging an amulet when only a sword is insured → error");
  it.todo("claim damaging an item with an unknown type → error");
  it.todo("claim with a damage entry of amount -200 → error");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");

  // --- CLI ---
