          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes (base premium 175 G, no block) → premium 198 G (197.5 rounded up in the MHPCO's favor)", () => {
