export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const basePremiumOfGroup = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumOfGroup(type, count),
    0,
  );

const firstInsuranceSurcharge = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;

const surchargeWhen = (applies: boolean, item: Item, rate: number): number =>
  applies ? BASE_PREMIUMS[item.type] * rate : 0;

const curseSurcharge = (item: Item): number =>
  surchargeWhen(item.cursed === true, item, CURSE_SURCHARGE_RATE);

const highEnchantmentSurcharge = (item: Item): number =>
  surchargeWhen(
    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    item,
    HIGH_ENCHANTMENT_SURCHARGE_RATE,
  );

const itemSurchargeTotal = (items: Item[]): number =>
  items.reduce(
    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
    0,
  );

const quote = (step: QuoteStep): QuoteResult => {
  const policyBase = policyBasePremium(step.items);
  const premiumBeforeRounding =
    policyBase +
    itemSurchargeTotal(step.items) +
    firstInsuranceSurcharge(policyBase) +
    PROCESSING_FEE;
  return { premium: Math.ceil(premiumBeforeRounding) };
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
};

