cat > /tmp/probe.mjs <<'EOF'
// Compare end-rounding vs per-term rounding across small policies.
const BASE = { rune: 25, amulet: 60, sword: 100, staff: 80, potion: 40 };
for (const type of Object.keys(BASE)) {
  for (let n = 1; n <= 3; n++) {
    for (const years of [0, 2]) {
      for (const second of [false, true]) {
        const base = n === 3 ? 60 : n * BASE[type];
        const fi = base * 0.1;
        const loy = years >= 2 ? base * 0.2 : 0;
        const fu = second ? base * 0.15 : 0;
        const endRounded = Math.ceil(base + fi - loy - fu + 5);
        const perTerm = base + Math.ceil(fi) - Math.floor(loy) - Math.floor(fu) + 5;
        if (endRounded !== perTerm) {
          console.log(`${n}x${type} years=${years} second=${second}: end=${endRounded} perTerm=${perTerm}`);
        }
      }
    }
  }
}
EOF
